package com.oveduumnakal.snakeweed;

/**
 * Spots a herb being harvested: the count of grimy snake weed in the backpack going up. Gains while the bank is open
 * are withdrawals, not harvests, and the first count after login or a world hop only sets the baseline.
 */
final class HarvestWatch
{
	private int last = -1;

	/**
	 * Takes in a new count of grimy snake weed.
	 *
	 * @param grimy    grimy snake weed now in the backpack
	 * @param bankOpen whether the bank interface is showing
	 * @return true when a herb was harvested since the last count
	 */
	boolean update(int grimy, boolean bankOpen)
	{
		int before = last;
		last = grimy;
		return before >= 0 && grimy > before && !bankOpen;
	}

	/** Forgets the count, for logout, a world hop, or when the plugin stops. */
	void reset()
	{
		last = -1;
	}
}

